#!/usr/bin/env python3
from __future__ import annotations
import json, pathlib, html, hashlib
ROOT=pathlib.Path(__file__).resolve().parent
M=json.loads((ROOT/'BRAINK_PUBLIC_CORPORATE_RELEASE.json').read_text())
OUT=ROOT/'dist'; OUT.mkdir(exist_ok=True)
COPY={
'braink.com.au':('BRAINK. Intelligence you can operate.','BRAINK AI · User Runtime','A governed AI environment that preserves semantic identity, continuation, evidence and user control across workspaces, applications and server-room runtimes.'),
'braink-intelligence.com.au':('Intelligence with lineage.','BRAINK Intelligence · Research · Enterprise','A professional intelligence surface for research, analysis, enterprise workflows and evidence-led decisions, grounded in BRAINK, KEX and IL-LLM.'),
'braink-learning.com.au':('Learning that keeps its context.','BRAINK Learning · Guided Knowledge','A learning environment where definitions, relations, observer state and continuation remain addressable as users learn, explore and build.'),
'keddeh.com':('Keddeh Systems','KEDDEH · BRAINK · IL-LLM · KEX','A user-first operating surface for AI work, tasks, files, evidence and domain services. System maintenance stays in the background; diagnostics remain available when needed.')}
T='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{lead}"><style>:root{{--bg:#071019;--ink:#f7fbff;--muted:#a8bac8;--line:#1d3445;--accent:#8de7ff}}*{{box-sizing:border-box}}body{{margin:0;font:16px/1.55 system-ui;background:radial-gradient(circle at 20% 0,#10263a 0,transparent 34%),var(--bg);color:var(--ink)}}a{{color:inherit}}.w{{max-width:1180px;margin:auto;padding:0 28px}}nav{{display:flex;justify-content:space-between;padding:24px 0;border-bottom:1px solid var(--line)}}.brand{{font-weight:800;letter-spacing:.12em}}.tag{{font-size:12px;color:var(--accent);text-transform:uppercase;letter-spacing:.16em}}main{{padding:90px 0}}h1{{font-size:clamp(48px,8vw,92px);line-height:.95;letter-spacing:-.055em;margin:12px 0 28px}}p{{color:var(--muted);max-width:760px;font-size:20px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:50px}}article{{border:1px solid var(--line);padding:25px;border-radius:18px;background:#0b1721}}button,.button{{display:inline-block;background:var(--ink);color:#071019;padding:14px 20px;border-radius:12px;text-decoration:none;font-weight:750;border:0}}@media(max-width:800px){{.grid{{grid-template-columns:1fr}}}}</style></head><body><div class="w"><nav><div><div class="brand">BRAINK</div><div class="tag">{domain}</div></div><div>KEDDEH Systems</div></nav><main><div class="tag">{kicker}</div><h1>{title}</h1><p>{lead}</p><p><a class="button" href="/auth/google/start?domain={domain}">Continue with Google</a></p><section class="grid"><article><h3>Governed corpus</h3><p>IL-LLM semantic identity, definitions, relations, observer state and continuation remain attributable.</p></article><article><h3>Resident runtime</h3><p>BRAINK orchestration, KEX execution, VFS workspaces and KEDDEH server-room mesh remain bound to this surface.</p></article><article><h3>Secure rails</h3><p>Google OAuth and Stripe operate through dedicated server processes. Site code never owns provider secret material.</p></article></section><p><button onclick="fetch('/payments/checkout',{{method:'POST',headers:{{'content-type':'application/json'}},body:JSON.stringify({{domain:'{domain}',product:'BRAINK'}})}}).then(r=>r.json()).then(x=>x.checkout_url?location.href=x.checkout_url:alert(x.error||x.status))">Start securely</button></p></main></div></body></html>'''

ROOT_T='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Keddeh Systems</title><meta name="description" content="{lead}"><style>
:root{{--bg:#06080d;--panel:#0d121a;--ink:#f4f7fb;--muted:#98a7b8;--line:#253141;--accent:#8de7ff;--ok:#78d9a6}}*{{box-sizing:border-box}}body{{margin:0;background:linear-gradient(180deg,#08111b 0,#06080d 42%);color:var(--ink);font:16px/1.5 system-ui,sans-serif}}a{{color:inherit;text-decoration:none}}.shell{{max-width:1240px;margin:auto;padding:0 24px}}header{{height:64px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}}.brand{{font-weight:800;letter-spacing:.11em}}.status{{font-size:13px;color:var(--muted)}}main{{padding:28px 0 54px}}.intro{{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:20px}}h1{{font-size:clamp(34px,5vw,64px);line-height:1;letter-spacing:-.04em;margin:8px 0}}.lead{{color:var(--muted);max-width:760px;font-size:18px}}.actions{{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px}}.card{{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;min-height:165px}}.card h2{{margin:4px 0 8px;font-size:21px}}.card p{{margin:0;color:var(--muted)}}.primary{{min-height:210px}}.row{{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}}button,.button{{border:0;border-radius:10px;padding:11px 15px;font:inherit;font-weight:700;cursor:pointer;background:var(--ink);color:#071019}}.secondary{{background:#152131;color:var(--ink);border:1px solid #2d435a}}details{{margin-top:16px;border-top:1px solid var(--line);padding-top:14px}}summary{{cursor:pointer;color:var(--muted)}}pre{{white-space:pre-wrap;word-break:break-word;color:#b7c7d8;font-size:12px}}.tiny{{font-size:12px;color:var(--muted)}}@media(max-width:900px){{.actions{{grid-template-columns:1fr}}.intro{{align-items:start;flex-direction:column}}}}</style></head><body><div class="shell"><header><div class="brand">KEDDEH SYSTEMS</div><div id="status" class="status">System status: checking</div></header><main><section class="intro"><div><div class="tiny">KEDDEH · BRAINK · IL-LLM · KEX</div><h1>Work from the outcome.</h1><p class="lead">{lead}</p></div><a class="button" href="/auth/google/start?domain=keddeh.com">Continue with Google</a></section><section class="actions"><article class="card primary"><div class="tiny">AI interaction</div><h2>Ask BRAINK</h2><p>Describe the work you want completed. The runtime resolves the required tools, evidence and continuation behind the interface.</p><div class="row"><button onclick="location.href='/auth/google/start?domain=keddeh.com'">Open BRAINK</button><button class="secondary" onclick="loadHome()">Refresh workspace</button></div></article><article class="card"><div class="tiny">Task management</div><h2>My work</h2><p id="tasks">Loading current work state…</p></article><article class="card"><div class="tiny">Files & evidence</div><h2>Files</h2><p id="files">Loading file/evidence state…</p></article></section><section class="actions" style="margin-top:14px"><article class="card"><div class="tiny">Domain services</div><h2>Websites</h2><p>Keddeh Systems domain and site work remains linked to the resident runtime and evidence plane.</p></article><article class="card"><div class="tiny">Learning fabric</div><h2>IL-LLM</h2><p>Semantic identity, definitions, relations, evidence and continuation remain addressable across the learning fabric.</p></article><article class="card"><div class="tiny">Runtime</div><h2>BRAINK / KEX</h2><p>Execution mechanics stay behind the workflow surface unless diagnostics are required.</p></article></section><details><summary>Diagnostics</summary><pre id="diag">Diagnostics load on demand.</pre><div class="row"><button class="secondary" onclick="loadDiagnostics()">Load diagnostics</button></div></details></main></div><script>
async function loadHome(){{try{{const r=await fetch('/home/summary',{{cache:'no-store'}});const x=await r.json();status.textContent='System status: '+(x.system?.sync||x.status||'available');tasks.textContent=x.tasks?.status==='UNBOUND'?'Task service is not yet bound to this public surface.':((x.tasks?.open_count??0)+' open items');files.textContent=x.files?.state==='UNBOUND'?'File service is not yet bound to this public surface.':'Files available';}}catch(e){{status.textContent='System status: unavailable';tasks.textContent='Work state unavailable';files.textContent='File state unavailable'}}}}
async function loadDiagnostics(){{try{{const r=await fetch('/diagnostics/summary',{{cache:'no-store'}});diag.textContent=JSON.stringify(await r.json(),null,2)}}catch(e){{diag.textContent='Diagnostics unavailable'}}}}
loadHome();
</script></body></html>'''
readback={'schema':'kex.braink.site-build.v1','domains':{},'overall':True}
for d,spec in M['domains'].items():
    title,kicker,lead=COPY[d]; p=OUT/d; p.mkdir(parents=True,exist_ok=True); f=p/'index.html'
    template=ROOT_T if d=='keddeh.com' else T
    f.write_text(template.format(domain=html.escape(d),title=html.escape(title),kicker=html.escape(kicker),lead=html.escape(lead)))
    readback['domains'][d]={'site':spec['site'],'runtime':spec['runtime'],'workspace':spec['workspace'],'vfs':spec['vfs'],'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'status':'BUILT'}
(ROOT/'SITE_BUILD_READBACK.json').write_text(json.dumps(readback,indent=2)); print(json.dumps(readback,indent=2))
